SELECT ST_Area_Spheroid(ST_Union_Agg(geometry)) / 1000000 AS total_area_km2
FROM countries
WHERE continent = 'South America';

WITH north AS (
  SELECT ST_MakeEnvelope(-180, 0, 180, 89.9) AS geom
),
africa_union AS (
  SELECT ST_Union_Agg(geometry) AS geom FROM countries WHERE continent = 'Africa'
)
SELECT ST_Area_Spheroid(ST_Intersection(africa_union.geom, north.geom)) / 1000000 AS north_africa_km2
FROM africa_union, north;

WITH sa AS (
  SELECT ST_Union_Agg(geometry) AS geom FROM countries WHERE continent = 'South America'
),
br AS (
  SELECT geometry AS geom FROM countries WHERE name = 'Brazil'
)
SELECT ST_Area_Spheroid(ST_Difference(sa.geom, br.geom)) / 1000000 AS sa_without_brazil_km2
FROM sa, br;
